def get_segments(grid, color):
    by_u={}
    for r,row in enumerate(grid):
        for c,x in enumerate(row):
            if x==color: by_u.setdefault(c-r,[]).append((r+c,r,c))
    segs=[]
    for u,pts in by_u.items():
        vs=sorted(v for v,_,_ in pts)
        groups=[]
        for v in vs:
            if not groups or v-groups[-1][-1]>2:groups.append([v])
            else:groups[-1].append(v)
        for g in groups:segs.append((u,g[0],g[-1]))
    return sorted(segs)
def fill_between(grid,color):
    segs=get_segments(grid,color)
    fill=set()
    # In transformed plane, for each v, pair adjacent active boundary lines and fill between them.
    all_v=range(0,2*(len(grid)-1)+1)
    for v in all_v:
        active=sorted({u for u,lo,hi in segs if lo<=v<=hi})
        for u1,u2 in zip(active,active[1:]):
            for u in range(u1+1,u2):
                if (u+v)%2: continue
                r=(v-u)//2;c=(v+u)//2
                if 0<=r<len(grid) and 0<=c<len(grid[0]) and grid[r][c]==8:
                    fill.add((r,c))
    return fill,segs
